import sys;sys.path.insert(0,'..')
from gcommon import *
SRC=srcs([GD('git-restore'),GD('git-reset'),GD('git-revert'),GD('git-reflog'),GD('git-commit','Git – git-commit (--amend)'),GD('git-clean'),GD('git-config','Git – git-config (gc.reflogExpire)')])
def dia(vi):
    t=('Mỗi lệnh hoàn tác lùi dữ liệu về vùng nào' if vi else 'Which area each undo command rewinds','Sơ đồ do Vinc Academy biên soạn.' if vi else 'Diagram by Vinc Academy.','dg-%s-g07'%('vi' if vi else 'en'))
    items=[(10,(['Thư mục','làm việc'],['Working','tree']),'',False),(235,(['Staging'],['Staging']),'',True),(460,(['Commit','(HEAD)'],['Commit','(HEAD)']),'',False)]
    b=''
    for x,ti,su,ac in items:
        b+='<rect class="%s" x="%d" y="45" width="170" height="70" rx="12" />\n'%('dg-accent' if ac else 'dg-box',x)
        for i,l in enumerate(ti[0 if vi else 1]): b+='<text class="dg-title" x="%d" y="%d">%s</text>\n'%(x+14,70+i*18,l)
    for x,l in [(184,'git restore'),(409,'restore --staged')]:
        b+='<path class="dg-arrow" d="M%d 80 h-26 m8 -6 l-8 6 l8 6" /><text class="dg-text" text-anchor="middle" x="%d" y="34">%s</text>\n'%(x+50,x+37,l)
    b+='<text class="dg-text" x="10" y="145">%s</text>\n'%('reset --soft: chỉ lùi HEAD · --mixed: lùi cả staging · --hard: lùi cả thư mục làm việc' if vi else 'reset --soft: moves only HEAD · --mixed: staging too · --hard: the working tree as well')
    b+='<text class="dg-text" x="10" y="168">%s</text>\n'%('revert: không lùi gì cả, thêm một commit mới có tác dụng ngược lại.' if vi else 'revert: rewinds nothing, it adds a commit that cancels the earlier one.')
    return fig('640 185',t[0],b,t[1],t[2])
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a07');base(sb)
    S1=sb.P('echo "# lỡ tay" >> models/course.py','git status -s','git restore models/course.py','git status -s')
    S2=sb.P('echo "# lỡ tay" >> models/course.py','git add models/course.py','git status -s','git restore --staged models/course.py','git status -s','git restore models/course.py')
    S3=sb.P('echo "# vinc_course" > README.md','git add README.md','git commit -m "[ADD] vinc_corse: README"','git commit --amend -m "[ADD] vinc_course: README"','echo "Module quản lý khóa học." >> README.md','git commit -qa --amend --no-edit','git log --oneline -n 2','git show --stat --oneline HEAD')
    S4=sb.P("echo \"    price = fields.Float(string='Học phí')\" >> models/course.py",'git commit -qam "[IMP] vinc_course: thêm học phí"',"echo \"    level = fields.Char(string='Cấp độ')\" >> models/course.py",'git commit -qam "[IMP] vinc_course: thêm cấp độ"','git reset --soft HEAD~1','git status -s','git log --oneline -n 2')
    S4b=sb.P('git commit -qm "[IMP] vinc_course: thêm cấp độ"','git reset HEAD~1','git status -s')
    S4c=sb.P('git commit -qam "[IMP] vinc_course: thêm cấp độ"','git reset --hard HEAD~1','git status -sb','grep -c level models/course.py')
    S5=sb.P('git reflog -n 3','git reset --hard HEAD@{1}','grep -c level models/course.py','git log --oneline -n 2')
    S6=sb.P('git revert --no-edit HEAD','git log --oneline -n 3','grep -c level models/course.py')
    S7=sb.P("echo \"    code = fields.Char(string='Mã')\" >> models/course.py",'git commit -qam "[IMP] vinc_course: thêm mã khóa (lẽ ra phải ở nhánh riêng)"','git branch feature/course-code','git reset --hard HEAD~1','git log --oneline --graph --all --decorate -n 4')
    S8=sb.P('echo "x" > tam.txt','git clean -n','git clean -f','git status -s')
    S9=sb.P('echo "# việc dang dở" >> models/course.py','git reset --hard HEAD','grep -c dang models/course.py','git reflog -n 2')
    S10=sb.P('git branch backup/truoc-reset','git reset --hard HEAD~1','git log --oneline -n 1','git reset --hard backup/truoc-reset','git log --oneline -n 1','git branch -d backup/truoc-reset')
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Mỗi loại sai lầm có một lệnh hoàn tác riêng; chọn đúng lệnh quan trọng hơn là nhớ nhiều lệnh.</strong> Sửa nhầm file: <code>git restore</code>. Lỡ <code>git add</code>: <code>git restore --staged</code>. Commit chưa push: <code>git commit --amend</code> hoặc <code>git reset</code> (<code>--soft</code>, mặc định <code>--mixed</code>, <code>--hard</code>). Commit đã push: <code>git revert</code>. Lỡ mất commit: <code>git reflog</code>. Bài này chạy từng lệnh trên repo <code>vinc_course</code> để bạn thấy chính xác cái gì mất, cái gì còn.','<strong>Every kind of mistake has its own undo command; choosing the right one matters more than remembering many.</strong> Edited the wrong file: <code>git restore</code>. Staged by mistake: <code>git restore --staged</code>. Unpushed commit: amend it or use <code>git reset</code> (<code>--soft</code>, default <code>--mixed</code>, <code>--hard</code>). Pushed commit: <code>git revert</code>. Lost a commit: <code>git reflog</code>. This part runs each command on the <code>vinc_course</code> repo so you see exactly what is lost and what stays.')))
    o+=h2('chon-lenh',t('Chọn đúng lệnh theo “mình đang ở đâu”','Pick the command by “where am I”'))
    o+=p(t('Bí quyết là xác định sai lầm đang nằm ở vùng nào trong ba vùng của bài 1, rồi lùi từ vùng đó. Có thêm một câu hỏi quyết định: commit đã được <strong>push</strong> lên GitLab chưa? Commit chưa push chỉ nằm trên máy bạn nên sửa lịch sử thoải mái; commit đã push là của cả nhóm, và viết lại lịch sử sẽ gây rối cho người khác.','The trick is to find which of the three areas from part 1 holds the mistake, then rewind from there. One more deciding question: has the commit been <strong>pushed</strong> to GitLab? An unpushed commit lives only on your machine so you may rewrite it freely; a pushed commit belongs to the team, and rewriting history confuses everyone else.'))
    o+=dia(vi)
    o+=tbl([t('Tình huống','Situation'),t('Lệnh','Command'),t('Mất gì?','What is lost?')],[
        [t('Sửa nhầm file, chưa add','Edited a file by mistake, not added'),'<code>git restore &lt;file&gt;</code>',t('Thay đổi chưa commit của file đó (không cứu lại được)','The uncommitted changes of that file (unrecoverable)')],
        [t('Lỡ <code>git add</code>','Added too much'),'<code>git restore --staged &lt;file&gt;</code>',t('Không mất gì, file vẫn giữ nguyên thay đổi','Nothing; the file keeps its changes')],
        [t('Sai message hoặc thiếu file ở commit mới nhất','Wrong message or missing file in the latest commit'),'<code>git commit --amend</code>',t('Commit cũ bị thay bằng commit mới (chỉ khi chưa push)','The old commit is replaced by a new one (only if unpushed)')],
        [t('Muốn bỏ commit chưa push','Drop unpushed commits'),'<code>git reset --soft / --mixed / --hard HEAD~N</code>',t('Tùy cờ, xem bảng dưới','Depends on the flag, see the table below')],
        [t('Commit đã push, cần đảo ngược','Pushed commit that must be undone'),'<code>git revert &lt;commit&gt;</code>',t('Không mất gì, thêm một commit mới','Nothing; adds a new commit')],
        [t('Lỡ reset/xóa nhánh, mất commit','Lost commits after reset or branch deletion'),'<code>git reflog</code>',t('Là lệnh để cứu lại','This is the rescue tool')]])
    o+=h2('restore',t('Hoàn tác thay đổi chưa commit: git restore','Undoing uncommitted changes: git restore'))
    o+=p(t('<code>git restore &lt;file&gt;</code> đưa file trong thư mục làm việc về đúng như trong staging (hoặc commit gần nhất nếu chưa staging). Hãy nhớ: thay đổi chưa commit mà bị restore thì <strong>không có cách nào cứu lại</strong>, vì Git chưa từng lưu nó. Còn <code>git restore --staged</code> chỉ rút file khỏi staging, thay đổi vẫn còn trong file nên hoàn toàn an toàn:','<code>git restore &lt;file&gt;</code> returns the file on disk to what staging holds (or to the latest commit if nothing is staged). Remember: restored uncommitted changes <strong>cannot be recovered</strong>, because Git never stored them. <code>git restore --staged</code> only pulls the file out of staging; the changes stay in the file, so it is perfectly safe:'))
    o+=S1+S2
    o+=p(t('Muốn lấy lại một file từ commit cũ, thêm <code>--source</code>: <code>git restore --source=HEAD~2 models/course.py</code> đưa file về phiên bản cách đây hai commit (vẫn là thay đổi chưa commit để bạn xem rồi quyết định).','To bring back a file from an older commit add <code>--source</code>: <code>git restore --source=HEAD~2 models/course.py</code> puts the file as it was two commits ago (still an uncommitted change, so you can look and then decide).'))
    o+=h2('amend',t('Sửa commit mới nhất: git commit --amend','Fixing the latest commit: git commit --amend'))
    o+=p(t('Gõ sai message hay quên một file? Đừng tạo thêm commit “fix typo”. <code>--amend</code> thay commit mới nhất bằng một commit mới có nội dung đã chỉnh. Mã băm đổi (trong ví dụ <code>87e…</code> thành mã khác), nghĩa là đây là <strong>commit khác</strong>; vì vậy chỉ nên amend khi chưa push:','Mistyped the message or forgot a file? Do not add a “fix typo” commit. <code>--amend</code> replaces the latest commit with a new one with the corrected content. The hash changes, meaning it is a <strong>different commit</strong>; that is why you should amend only before pushing:'))
    o+=S3
    o+=h2('reset',t('Bỏ commit chưa push: git reset','Dropping unpushed commits: git reset'))
    o+=p(t('<code>git reset &lt;commit&gt;</code> di chuyển nhánh hiện tại về commit đó. Ba cờ quyết định phần còn lại (theo tài liệu): <code>--soft</code> giữ nguyên cả staging lẫn thư mục làm việc; <code>--mixed</code> (mặc định) cập nhật staging theo commit mới, giữ thư mục làm việc; <code>--hard</code> ghi đè cả thư mục làm việc. Thử với hai commit học phí và cấp độ:','<code>git reset &lt;commit&gt;</code> moves the current branch to that commit. Three flags decide the rest (per the documentation): <code>--soft</code> leaves both staging and the working tree untouched; <code>--mixed</code> (the default) updates staging to match the new commit and leaves the working tree; <code>--hard</code> overwrites the working tree as well. Try it with the price and level commits:'))
    o+=tbl([t('Cờ','Flag'),t('HEAD / nhánh','HEAD / branch'),t('Staging','Staging'),t('Thư mục làm việc','Working tree')],[['<code>--soft</code>',t('lùi','moves back'),t('giữ','kept'),t('giữ','kept')],['<code>--mixed</code>',t('lùi','moves back'),t('theo commit mới','matches new HEAD'),t('giữ','kept')],['<code>--hard</code>',t('lùi','moves back'),t('theo commit mới','matches new HEAD'),t('<strong>bị ghi đè</strong>','<strong>overwritten</strong>')]])
    o+=S4
    o+=p(t('<code>--soft</code> đưa thay đổi của commit bị bỏ trở lại staging (<code>M </code> ở cột trái), tiện khi bạn muốn <em>gộp lại hoặc viết lại commit</em>. Commit lại rồi thử <code>--mixed</code>: thay đổi chuyển thành chưa staging:','<code>--soft</code> puts the dropped commit\'s changes back into staging (<code>M </code> in the left column), handy when you want to <em>combine or rewrite commits</em>. Commit again and try <code>--mixed</code>: the changes become unstaged:'))
    o+=S4b
    o+=p(t('Cuối cùng là <code>--hard</code>: vừa lùi nhánh vừa xóa thay đổi khỏi thư mục làm việc (<code>grep</code> đếm 0 vì dòng <code>level</code> đã biến mất):','Finally <code>--hard</code>: it moves the branch and also wipes the changes from the working tree (<code>grep</code> counts 0 because the <code>level</code> line is gone):'))
    o+=S4c
    o+=h2('reflog',t('Cứu commit “đã mất”: git reflog','Rescuing “lost” commits: git reflog'))
    o+=p(t('Commit vừa bị <code>reset --hard</code> thật ra chưa biến mất: Git ghi lại mọi lần HEAD di chuyển trong <em>reflog</em>. Chỉ cần tìm dòng <code>HEAD@{n}</code> trước khi sai và đưa nhánh về đó. Theo tài liệu <code>git config</code>, mục reflog được giữ mặc định 90 ngày (30 ngày cho mục không còn nối với nhánh nào), nên hãy cứu sớm:','The commit that <code>reset --hard</code> just dropped has not really vanished: Git records every HEAD movement in the <em>reflog</em>. Find the <code>HEAD@{n}</code> entry from before the mistake and move the branch back to it. According to the <code>git config</code> documentation, reflog entries are kept for 90 days by default (30 days for entries no longer reachable from any branch), so rescue early:'))
    o+=S5
    o+=p(t('Hai cách đếm này hay bị nhầm. <code>HEAD~1</code>, <code>HEAD~2</code> đếm lùi theo <em>lịch sử commit</em> của nhánh (cha, ông). <code>HEAD@{1}</code> đếm lùi theo <em>reflog</em>, tức là vị trí HEAD ở những lần di chuyển trước đó, kể cả những commit giờ không còn nằm trên nhánh. Vì vậy sau một lần <code>reset --hard</code>, <code>HEAD~1</code> đưa bạn lùi tiếp, còn <code>HEAD@{1}</code> đưa bạn quay về chỗ cũ.','These two ways of counting are easy to mix up. <code>HEAD~1</code> and <code>HEAD~2</code> count back through the branch\'s <em>commit history</em> (parent, grandparent). <code>HEAD@{1}</code> counts back through the <em>reflog</em>, meaning where HEAD stood at earlier moves, including commits no longer on the branch. So after a <code>reset --hard</code>, <code>HEAD~1</code> takes you further back while <code>HEAD@{1}</code> takes you back where you were.'))
    o+=h2('revert',t('Đảo ngược commit đã push: git revert','Reversing a pushed commit: git revert'))
    o+=p(t('Khi commit đã lên GitLab, đừng reset rồi ép push: người khác đã có commit đó. Hãy dùng <code>git revert</code>, lệnh tạo một commit <strong>mới</strong> làm điều ngược lại. Lịch sử giữ nguyên, ai kéo về cũng nhận được bản sửa:','Once a commit is on GitLab, do not reset and force-push: others already have it. Use <code>git revert</code>, which makes a <strong>new</strong> commit whose effect is the reverse. History stays intact and anyone who pulls receives the fix:'))
    o+=S6
    o+=p(t('Để revert một <em>merge commit</em> bạn phải chỉ rõ nhánh cha nào là “dòng chính” bằng <code>-m 1</code> (tham số <code>--mainline</code> trong tài liệu), thường là phía <code>main</code>. Revert merge là cách xử lý chuẩn khi một merge request đã vào <code>main</code> mà gây lỗi trên môi trường thử.','To revert a <em>merge commit</em> you must say which parent counts as the “mainline” with <code>-m 1</code> (the <code>--mainline</code> option in the documentation), usually the <code>main</code> side. Reverting a merge is the standard response when a merge request already in <code>main</code> breaks the staging environment.'))
    o+=h2('khac',t('Hai tình huống thường gặp khác','Two more common situations'))
    o+=p(t('<strong>Commit nhầm lên <code>main</code> (nhắc ở bài 3).</strong> Giữ công việc bằng cách tạo nhánh tại commit hiện tại, rồi đưa <code>main</code> lùi lại. Cả hai cùng trỏ đúng thứ tự an toàn, không mất commit nào:','<strong>Committed on <code>main</code> by mistake (mentioned in part 3).</strong> Keep the work by creating a branch at the current commit, then move <code>main</code> back. Done in this order it is safe and no commit is lost:'))
    o+=S7
    o+=p(t('<strong>Dọn file chưa theo dõi.</strong> <code>git clean</code> xóa file untracked; hãy luôn chạy <code>-n</code> (dry-run) trước để xem nó sẽ xóa gì, vì file đã xóa kiểu này không nằm trong reflog:','<strong>Cleaning untracked files.</strong> <code>git clean</code> deletes untracked files; always run <code>-n</code> (dry run) first to see what it would remove, because files deleted this way are not in the reflog:'))
    o+=S8
    o+=h2('luoi-an-toan',t('Lưới an toàn trước khi làm điều mạo hiểm','A safety net before anything risky'))
    o+=p(t('Reflog là lưới cuối cùng, nhưng có cách rẻ hơn để không phải dùng đến nó: trước khi chạy một lệnh bạn chưa chắc (<code>reset --hard</code>, <code>rebase</code>, <code>clean</code>), hãy <strong>tạo một nhánh sao lưu</strong> tại vị trí hiện tại. Nhánh chỉ là con trỏ nên tạo tức thì, và nếu mọi thứ ổn bạn xóa nó đi. Nếu hỏng, bạn đưa nhánh làm việc về lại đúng chỗ đã đánh dấu:','The reflog is the last net, but there is a cheaper way never to need it: before a command you are unsure about (<code>reset --hard</code>, <code>rebase</code>, <code>clean</code>), <strong>create a backup branch</strong> at the current position. A branch is only a pointer so it is instant, and if all goes well you delete it. If something breaks, move the working branch back to the marked spot:'))
    o+=S10
    o+=p(t('Thói quen này đặc biệt đáng giá trong tuần phát hành, khi áp lực cao và bạn dễ gõ nhầm. Cùng với việc luôn đọc <code>git status</code> và <code>git log --oneline</code> trước khi hoàn tác, nó biến những lệnh “đáng sợ” thành thao tác thường nhật.','This habit is especially valuable in release week, when pressure is high and typos are easy. Together with always reading <code>git status</code> and <code>git log --oneline</code> before undoing anything, it turns the “scary” commands into everyday operations.'))
    o+=h2('trong-odoo',t('Hoàn tác trong công việc Odoo','Undoing in Odoo work'))
    o+=tbl([t('Tình huống','Situation'),t('Cách xử lý','How to handle it')],[
        [t('Lỡ commit <code>odoo.conf</code> chứa mật khẩu','Committed <code>odoo.conf</code> with a password'),t('Chưa push: <code>reset --soft</code> hoặc <code>amend</code>. Đã push: đổi mật khẩu trước, rồi xử lý lịch sử cùng quản trị viên','Unpushed: <code>reset --soft</code> or <code>amend</code>. Pushed: rotate the password first, then deal with history with an admin')],
        [t('MR đã vào <code>main</code> làm hỏng bản thử','A merged MR breaks the test server'),t('<code>git revert -m 1 &lt;merge-commit&gt;</code> rồi push; sửa lỗi ở nhánh mới và merge lại','<code>git revert -m 1 &lt;merge-commit&gt;</code>, push, then fix on a new branch and merge again')],
        [t('Sửa nhầm file view XML đang làm dở','Broke a half-edited XML view'),t('<code>git restore views/course_views.xml</code> (chấp nhận mất phần chưa commit)','<code>git restore views/course_views.xml</code> (accept losing the uncommitted part)')],
        [t('Commit tên module sai ở tiêu đề','Wrong module name in the commit title'),t('<code>git commit --amend -m "[FIX] vinc_course: ..."</code> nếu chưa push','<code>git commit --amend -m "[FIX] vinc_course: ..."</code> if unpushed')]])
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong><code>git reset --hard</code> khi còn việc dang dở.</strong> Lệnh này xóa thay đổi chưa commit và reflog không cứu được vì Git chưa từng lưu chúng. Trong ví dụ dưới, dòng dang dở biến mất hoàn toàn, reflog chỉ ghi lần di chuyển HEAD, không có nội dung file:','<strong><code>git reset --hard</code> with work in progress.</strong> It wipes uncommitted changes and the reflog cannot save them because Git never stored them. In the example below the unfinished line vanishes completely; the reflog only records the HEAD movement, not file content:'),
        S9,
        t('<strong>Amend hoặc reset commit đã push rồi ép push.</strong> Người khác đã kéo commit cũ nên lịch sử của họ lệch với remote và rất dễ mất công việc. Với commit đã push, hãy <code>revert</code>.','<strong>Amending or resetting a pushed commit and force-pushing.</strong> Others already pulled the old commit, so their history diverges from the remote and work gets lost easily. For pushed commits use <code>revert</code>.'),
        t('<strong>Nhầm <code>restore</code> với <code>reset</code>.</strong> <code>restore</code> thao tác trên file, <code>reset</code> di chuyển nhánh. Khi chỉ muốn hủy một file, đừng dùng <code>reset --hard</code> vì nó đụng tới mọi file.','<strong>Mixing up <code>restore</code> and <code>reset</code>.</strong> <code>restore</code> works on files, <code>reset</code> moves the branch. If you only want to discard one file, avoid <code>reset --hard</code> because it touches every file.'),
        t('<strong>Hoảng khi thấy “mất” commit.</strong> Hãy dừng lại, chạy <code>git reflog</code> và tìm mã băm; chừng nào còn trong reflog, bạn vẫn lấy lại được bằng <code>git reset --hard &lt;mã&gt;</code> hoặc <code>git switch -c cứu &lt;mã&gt;</code>.','<strong>Panicking over a “lost” commit.</strong> Stop, run <code>git reflog</code> and find the hash; while it is still in the reflog you can get it back with <code>git reset --hard &lt;hash&gt;</code> or <code>git switch -c rescue &lt;hash&gt;</code>.')])
    o+=h2('tong-ket',t('Tổng kết','Summary'))
    o+=ul([t('Chưa commit: <code>restore</code> (file) và <code>restore --staged</code> (staging).','Not committed: <code>restore</code> (files) and <code>restore --staged</code> (staging).'),t('Commit chưa push: <code>--amend</code> hoặc <code>reset</code> (<code>--soft</code> giữ staging, <code>--mixed</code> giữ file, <code>--hard</code> xóa hết).','Unpushed commit: <code>--amend</code> or <code>reset</code> (<code>--soft</code> keeps staging, <code>--mixed</code> keeps files, <code>--hard</code> wipes all).'),t('Commit đã push: <code>revert</code>, đừng viết lại lịch sử chung.','Pushed commit: <code>revert</code>; never rewrite shared history.'),t('Mất commit: <code>git reflog</code> (còn 90 ngày mặc định), nhưng không cứu được thay đổi chưa từng commit.','Lost a commit: <code>git reflog</code> (90 days by default), which cannot save changes that were never committed.')])
    o+=p(t('Bạn đã biết sửa sai an toàn. Bài tiếp theo là thao tác mà nhiều người e ngại nhưng nhóm nào cũng dùng: <strong>rebase</strong> để làm gọn lịch sử trước khi mở merge request, và quy tắc vàng để không bao giờ gây họa với nó.','You can now fix mistakes safely. The next part is the operation many people fear yet every team uses: <strong>rebase</strong>, to tidy history before opening a merge request, and the golden rule that keeps it from ever causing harm.'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
